package vn.teaching.preparation;

import com.google.gson.*;
import org.junit.jupiter.api.Test;
import java.net.*;
import java.util.concurrent.CancellationException;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

class PreparationAuthoringApiTest {
    @Test void defaultAdapterAndIntegralMinutesMatchTheAppSchema(){
        JsonObject saved=PreparationAuthoringApi.configure(new JsonObject(),new JsonObject());assertEquals("openai-compatible",saved.get("authoringProvider").getAsString());
        JsonObject d=draft();d.getAsJsonArray("sections").get(0).getAsJsonObject().addProperty("minutes",1.5);assertThrows(RuntimeException.class,()->PreparationAuthoringApi.validateDraft(d,"en"));
    }
    JsonObject object(String json){return JsonParser.parseString(json).getAsJsonObject();}
    JsonObject config(){return object("{\"authoringProvider\":\"openai-compatible\",\"authoringBaseUrl\":\"https://provider.example/v1\",\"authoringModel\":\"configured-model\"}");}
    JsonObject request(){return object("{\"text\":\"Explain water cycle\",\"language\":\"en\",\"document\":{\"teacherNotes\":\"PRIVATE_ANSWER\"}}");}
    JsonObject draft(){return object("{\"sections\":[{\"id\":\"s1\",\"title\":\"Water\",\"body\":\"Water cycle\",\"objective\":\"\",\"teacherNotes\":\"Check understanding\",\"minutes\":5}],\"scenes\":[{\"id\":\"c1\",\"title\":\"Water\",\"text\":\"Water cycle\",\"narration\":\"Water cycle\",\"language\":\"en\",\"template\":\"diagram\"}]}");}
    String envelope(JsonObject draft){JsonObject message=new JsonObject();message.addProperty("content",draft.toString());JsonObject choice=new JsonObject();choice.addProperty("finish_reason","stop");choice.add("message",message);JsonArray choices=new JsonArray();choices.add(choice);JsonObject response=new JsonObject();response.add("choices",choices);return response.toString();}
    PreparationAuthoringApi api(PreparationAuthoringApi.Transport transport){return new PreparationAuthoringApi(()->"SERVER_SECRET",()->"provider.example",host->new InetAddress[]{InetAddress.getByAddress(new byte[]{8,8,8,8})},transport);}
    @Test void statusNeverCallsProviderOrExposesKey(){AtomicInteger calls=new AtomicInteger();JsonObject status=api((u,k,b,c)->{calls.incrementAndGet();throw new AssertionError();}).status(config());assertTrue(status.get("ready").getAsBoolean());assertFalse(status.toString().contains("SERVER_SECRET"));assertEquals(0,calls.get());}
    @Test void keyAndProviderMustBeConfigured(){var api=new PreparationAuthoringApi(()->null,()->"provider.example",h->new InetAddress[0],(u,k,b,c)->{throw new AssertionError();});assertFalse(api.status(config()).get("ready").getAsBoolean());assertThrows(RuntimeException.class,()->api.author(request(),config(),()->false));JsonObject old=config();old.remove("authoringProvider");assertFalse(api((u,k,b,c)->null).status(old).get("ready").getAsBoolean());}
    @Test void sendsOnlyExplicitSourceAndReturnsReviewedDraft(){AtomicInteger calls=new AtomicInteger();var api=api((uri,key,body,cancel)->{calls.incrementAndGet();assertEquals("https://provider.example/v1/chat/completions",uri.toString());assertEquals("SERVER_SECRET",key);assertFalse(body.contains("PRIVATE_ANSWER"));assertFalse(body.contains("document"));assertTrue(body.contains("Explain water cycle"));return new PreparationAuthoringApi.Reply(200,envelope(draft()));});JsonObject result=api.author(request(),config(),()->false);assertEquals("third-party-api",result.get("method").getAsString());assertTrue(result.get("reviewRequired").getAsBoolean());assertEquals(1,calls.get());}
    @Test void rejectsUnsafeEndpointsAndClientSecrets(){for(String endpoint:new String[]{"http://provider.example/v1","https://user:password@provider.example/v1","https://provider.example/v1?key=secret","https://provider.example/v1#fragment","https://localhost/v1","https://provider.example:8443/v1","https://provider.example/%2e%2e"}){JsonObject input=config();input.addProperty("authoringBaseUrl",endpoint);assertThrows(RuntimeException.class,()->PreparationAuthoringApi.configure(input,new JsonObject()),endpoint);}JsonObject input=config();input.addProperty("apiKey","SECRET");assertThrows(RuntimeException.class,()->PreparationAuthoringApi.configure(input,new JsonObject()));}
    @Test void removesLegacyLocalAuthoringConfiguration(){JsonObject current=object("{\"ollamaUrl\":\"http://localhost:11434\",\"authoringModelPath\":\"local\",\"modelRoot\":\"speech-models\"}");JsonObject result=PreparationAuthoringApi.configure(config(),current);assertFalse(result.has("ollamaUrl"));assertFalse(result.has("authoringModelPath"));assertEquals("speech-models",result.get("modelRoot").getAsString());}
    @Test void blocksPrivateAddressesBeforeCallingTransport()throws Exception{for(String address:new String[]{"127.0.0.1","10.0.0.1","169.254.169.254","192.168.1.1","100.64.0.1","::1","fc00::1"}){var api=new PreparationAuthoringApi(()->"SECRET",()->"provider.example",h->new InetAddress[]{InetAddress.getByName(address)},(u,k,b,c)->{throw new AssertionError();});assertThrows(RuntimeException.class,()->api.author(request(),config(),()->false));}}
    @Test void rejectsAssetInjectionAndInvalidOutput(){for(String kind:new String[]{"sections","scenes"}){JsonObject d=draft();d.getAsJsonArray(kind).get(0).getAsJsonObject().addProperty("imagePath","SECRET_PATH");RuntimeException error=assertThrows(RuntimeException.class,()->api((u,k,b,c)->new PreparationAuthoringApi.Reply(200,envelope(d))).author(request(),config(),()->false));assertFalse(error.getMessage().contains("SECRET_PATH"));}JsonObject d=draft();d.getAsJsonArray("scenes").get(0).getAsJsonObject().addProperty("language","vi");assertThrows(RuntimeException.class,()->PreparationAuthoringApi.validateDraft(d,"en"));}
    @Test void rejectsInvalidSourceBeforePaidCall(){AtomicInteger calls=new AtomicInteger();var api=api((u,k,b,c)->{calls.incrementAndGet();return null;});for(String source:new String[]{"","x".repeat(40_001)}){JsonObject r=request();r.addProperty("text",source);assertThrows(RuntimeException.class,()->api.author(r,config(),()->false));}assertEquals(0,calls.get());}
    @Test void cancellationAndErrorsNeverRetryOrExposeProviderContent(){AtomicInteger calls=new AtomicInteger();var api=api((u,k,b,c)->{calls.incrementAndGet();return new PreparationAuthoringApi.Reply(500,"SERVER_SECRET PRIVATE_ANSWER");});assertThrows(CancellationException.class,()->api.author(request(),config(),()->true));assertEquals(0,calls.get());RuntimeException error=assertThrows(RuntimeException.class,()->api.author(request(),config(),()->false));assertFalse(error.getMessage().contains("SERVER_SECRET"));assertEquals(1,calls.get());}
    @Test void oversizedBodyAndTruncationFailSafely(){assertThrows(RuntimeException.class,()->api((u,k,b,c)->new PreparationAuthoringApi.Reply(200,"x".repeat(PreparationAuthoringApi.MAX_RESPONSE+1))).author(request(),config(),()->false));String truncated=envelope(draft()).replace("\"stop\"","\"length\"");assertThrows(RuntimeException.class,()->api((u,k,b,c)->new PreparationAuthoringApi.Reply(200,truncated)).author(request(),config(),()->false));}
    @Test void validatesIdsNumericTypesAndSceneLengths(){for(String invalid:new String[]{"../file","has spaces",""}){JsonObject d=draft();d.getAsJsonArray("scenes").get(0).getAsJsonObject().addProperty("id",invalid);assertThrows(RuntimeException.class,()->PreparationAuthoringApi.validateDraft(d,"en"));}JsonObject d=draft();d.getAsJsonArray("sections").get(0).getAsJsonObject().addProperty("minutes","5");assertThrows(RuntimeException.class,()->PreparationAuthoringApi.validateDraft(d,"en"));JsonObject longScene=draft();longScene.getAsJsonArray("scenes").get(0).getAsJsonObject().addProperty("text","x".repeat(1801));assertThrows(RuntimeException.class,()->PreparationAuthoringApi.validateDraft(longScene,"en"));}
    @Test void boundedSubscriberCancelsBeforeRetainingOversizedPayload(){PreparationAuthoringApi.LimitedBody subscriber=new PreparationAuthoringApi.LimitedBody();AtomicInteger cancelled=new AtomicInteger();subscriber.onSubscribe(new java.util.concurrent.Flow.Subscription(){public void request(long count){}public void cancel(){cancelled.incrementAndGet();}});subscriber.onNext(java.util.List.of(java.nio.ByteBuffer.wrap(new byte[PreparationAuthoringApi.MAX_RESPONSE+1])));assertEquals(1,cancelled.get());assertEquals(0,subscriber.bytes.size());assertTrue(subscriber.result.isCompletedExceptionally());}
    @Test void serverAllowlistPinsCredentialDestinationBeforeDnsOrTransport(){AtomicInteger calls=new AtomicInteger();for(String allowed:new String[]{"","other.example","*.example","https://provider.example","provider.example.attacker.test"}){var api=new PreparationAuthoringApi(()->"SERVER_SECRET",()->allowed,host->{calls.incrementAndGet();throw new AssertionError();},(u,k,b,c)->{calls.incrementAndGet();throw new AssertionError();});assertFalse(api.status(config()).get("ready").getAsBoolean());assertFalse(api.status(config()).get("hostAllowed").getAsBoolean());RuntimeException error=assertThrows(RuntimeException.class,()->api.author(request(),config(),()->false));assertFalse(error.getMessage().contains("SERVER_SECRET"));}assertEquals(0,calls.get());assertTrue(new PreparationAuthoringApi(()->"SERVER_SECRET",()->"other.example, PROVIDER.EXAMPLE",h->new InetAddress[0],(u,k,b,c)->null).status(config()).get("ready").getAsBoolean());}
}
